export const MQ_MARKETPLACES = [
  "ebay",
  "poshmark",
  "etsy",
  "shopify",
  "depop",
  "whatnot",
] as const;

export const getSendOfferMarketplaces = (params?: {
  countryCode?: CountryCodeType;
}): MarketplaceIDType[] => {
  const countryCode = params?.countryCode || "US";

  if (countryCode !== "US") return ["ebay", "depop"];

  return ["ebay", "poshmark", "mercari", "depop", "grailed", "vestiaire"];
};

export const getMarketplaceSharingMarketplaces = (params?: {
  countryCode?: CountryCodeType;
}): MarketplaceIDType[] => {
  const countryCode = params?.countryCode || "US";

  if (countryCode !== "US") return ["depop"];

  return ["depop", "poshmark", "grailed"];
};

export const MARKETPLACES_NOT_LISTABLE = ["sellhound", "kidizen", "tradesy"];

export const LISTABLE_MARKETPLACES = MARKETPLACES.filter(
  marketplace => !MARKETPLACES_NOT_LISTABLE.includes(marketplace)
) as Array<ListableMarketplaceIDType>;

export const isListableMarketplace = (
  m: MarketplaceIDType
): m is ListableMarketplaceIDType =>
  LISTABLE_MARKETPLACES.includes(m as ListableMarketplaceIDType);

export const marketplaceOptions = MARKETPLACES.map(id => ({
  label: marketplaceNames(id),
  value: id,
}));

export const isMqSupportedMarketplace = (
  mk: "general" | AllMarketplaceIDType
): mk is typeof MQ_MARKETPLACES[number] =>
  mk === "general" || MQ_MARKETPLACES.some(m => m == mk);

export default MARKETPLACES;

export type ExtensionMarketplacesIDType = typeof EXTENSION_MARKETPLACES[number];
export type ApiMarketplacesIDType = typeof API_MARKETPLACES[number];
export type MsvcMarketplacesIDType = typeof MSVC_MARKETPLACES[number];

