import userEvent from "@testing-library/user-event";
import { getWaitForElementSelector } from "@vendoo/common/extension/utils/waitElement";
import {
  ExecPageScriptActionsType,
  HoverActionType,
} from "@vendoo/common/types/v2/messaging/ExecPageScript";

const isHoverAction = (
  action: ExecPageScriptActionsType
): action is HoverActionType => action && action.type === "hover";

export const hoverActionHandler = async (
  action: ExecPageScriptActionsType,
  _rootFrameElement: HTMLElement
) => {
  if (!isHoverAction(action)) return;

  const findSelector = getWaitForElementSelector(action.isxPath);
  const element = await findSelector<HTMLElement>(action.selector);
  userEvent.hover(element);
};
