import { getFromStorage } from "@vendoo/common/extension/utils/getFromStorage";
import {
  ExecPageScriptActionsType,
  GetFromStorage,
} from "@vendoo/common/types/v2/messaging/ExecPageScript";

const isGetFromStorageAction = (
  action: ExecPageScriptActionsType
): action is GetFromStorage => action && action.type === "getFromStorage";

export const getFromStorageHandler = async (
  action: ExecPageScriptActionsType,
  _rootFrameElement: HTMLElement
) => {
  if (!isGetFromStorageAction(action)) return;
  return getFromStorage(action);
};
