import get from "lodash/get";

import errorDictionary from "@vendoo/common/dictionary/errors";
import { VendooError } from "@vendoo/common/errors/vendoo";
import { ExtensionV3WebRequestCommand } from "@vendoo/common/messaging/connection/types";
import {
  ExecPageScriptActionsType,
  MercariListActionType,
} from "@vendoo/common/types/v2/messaging/ExecPageScript";

import getErrorMessage from "@vendoo/marketplaces/src/mercari/errors/getErrorMessage";
import {
  getListItemRequestConfig,
  getMultiUploadImageRequestConfig,
} from "@vendoo/marketplaces/src/mercari/handlers/list/utils/requests";

import { webRequest } from "../../../../webRequest";
import { MERCARI } from "@vendoo/marketplaces/src/mercari/utils/constants";

const isMercariListAction = (
  action: ExecPageScriptActionsType
): action is MercariListActionType => action && action.type === "mercariList";

export const mercariListActionHandler = async (
  action: ExecPageScriptActionsType,
  _rootFrameElement: HTMLElement
) => {
  if (!isMercariListAction(action)) return;
  const { extras, config, images, item } = action.payload;

  const imageIds = await webRequest(
    {
      configRequest: getMultiUploadImageRequestConfig({
        config,
        extras,
        images,
      }),
    },
    {} as ExtensionV3WebRequestCommand
  ).then(({ data: imgUploadResponse }) => {
    const imageIds = get(imgUploadResponse.data, [
      "uploadTempListingPhotos",
      "uploadIds",
    ]) as string[];
    if (imageIds) return imageIds;

    throw new VendooError(
      getErrorMessage(
        imgUploadResponse.errors,
        errorDictionary.errorDownloadingImage
      ),
      {},
      {
        errorMessage: imgUploadResponse.errors
          ? JSON.stringify(imgUploadResponse.errors, null, 2)
          : "",
      }
    );
  });

  item.photoIds = imageIds;

  const { data: listingResponse } = await webRequest(
    {
      configRequest: getListItemRequestConfig({
        config,
        extras,
        item,
      }),
    },
    {} as ExtensionV3WebRequestCommand
  );
  const { data, errors } = listingResponse;
  if (!data)
    throw new VendooError(
      getErrorMessage(errors, errorDictionary.list.listingError),
      {},
      { errorMessage: errors ? JSON.stringify(errors, null, 2) : "" }
    );

  const listedID = get(data, ["createListing", "id"]);

  if (!listedID)
    throw new VendooError(errorDictionary.list.listingError, {
      alertTeam: true,
    });

  return JSON.stringify({
    listedID: String(listedID),
    listingURL: MERCARI.createListingUrl(listedID),
  });
};
