import { getWaitForElementSelector } from "@vendoo/common/extension/utils/waitElement";
import {
  ExecPageScriptActionsType,
  WaitForElementActionType,
} from "@vendoo/common/types/v2/messaging/ExecPageScript";

const isWaitForElementAction = (
  action: ExecPageScriptActionsType
): action is WaitForElementActionType =>
  action && action.type === "waitForElement";

export const waitForElementHandler = async (
  action: ExecPageScriptActionsType,
  rootFrameElement: HTMLElement
) => {
  if (!isWaitForElementAction(action)) return;

  await getWaitForElementSelector(action.isxPath)(
    action.selector,
    undefined,
    rootFrameElement
  );
};
