import cloneDeep from "lodash/cloneDeep";

import { transformHandlers } from "./utils/transformHandlers";

// Types
import { VendooRequestConfigType } from "@vendoo/common/types/sendWebRequest";

export const VendooTransformRequest = (config: VendooRequestConfigType) => {
  if (config.headers?.["vendoo-transform-request"]) {
    const transformRequest = cloneDeep(
      config.headers["vendoo-transform-request"]
    );
    const handler = transformHandlers[transformRequest.type];

    delete config.headers["vendoo-transform-request"];

    if (handler) {
      const data = handler({
        data: config.data,
        ...transformRequest,
      });
      config.data = data;
      return config;
    }
  }
  return config;
};
