import { AxiosResponse } from "axios";
import { ExtensionV3WebRequestCommand } from "@vendoo/common/messaging/connection/types";

import { VendooTransformRequest } from "@vendoo/extension-v3/src/serviceWorker/services/webRequest/proxy/interceptors/vendoo-transform-request";
import { VendooTransformFields } from "@vendoo/extension-v3/src/serviceWorker/services/webRequest/proxy/interceptors/vendoo-transform-fields";
import { VendooRequestConfigType } from "@vendoo/common/types/sendWebRequest";
import { Logger } from "@vendoo/common/context/shared/resolve";
import { VendooError } from "@vendoo/common/errors/vendoo";

import { axiosRequestWithDefaults } from "./utils/axiosRequestWithDefaults";
import { createFetchRequest } from "./utils/createFetchRequest";

const interceptors = [VendooTransformFields, VendooTransformRequest];

const dispatchFetchRequest = async (request: Request): Promise<Response> => {
  try {
    return await fetch(request);
  } catch (err) {
    throw VendooError.fromError(err, "Failed to fetch request", {
      alertTeam: true,
      allowRetry: true,
    });
  }
};

export const webRequest = async (
  // Request sent by the web-app
  params: { configRequest: VendooRequestConfigType },
  _message: ExtensionV3WebRequestCommand
) => {
  // Config request is using the request shape from axios (VendooRequestConfigType)
  let axiosRequestConfig = axiosRequestWithDefaults(params.configRequest);

  // Apply the interceptors
  for (let i of interceptors) {
    // Each interceptor return a new config
    axiosRequestConfig = i(axiosRequestConfig);
  }

  const fetchRequest = createFetchRequest(axiosRequestConfig);

  // Send the request and handle errors
  const fetchResponse = await dispatchFetchRequest(fetchRequest);

  // We need to answer with axios shape
  const response: AxiosResponse = {
    status: fetchResponse.status, // status might not be 200, and this is ok
    statusText: fetchResponse.statusText,
    headers: new Headers(fetchResponse.headers),
    config: axiosRequestConfig,
    data: null,
    request: fetchRequest,
  };

  const contentType = response.headers.get("content-type") ?? "";

  if (contentType.includes("application/octet-stream")) {
    response.data = await fetchResponse.blob();
  } else {
    response.data = await fetchResponse.text();

    // Make sure if not a JSON response, we return the data as a string
    try {
      response.data = JSON.parse(response.data);
    } catch (err) {
      Logger().debug("Failed to parse json response, falling back to text", {
        data: response.data,
      });
    }
  }

  return response;
};
