import get from "lodash/get";
import set from "lodash/set";

// Types
import {
  VendooRequestConfigType,
  VendooTransformFieldsType,
} from "@vendoo/common/types/sendWebRequest";

import { safeParse } from "./utils/safeParse";
import { transformHandlers } from "./utils/transformHandlers";

export const VendooTransformFields = (config: VendooRequestConfigType) => {
  if (config.headers?.["vendoo-transform-fields"]) {
    const transformFields = safeParse<VendooTransformFieldsType[]>(
      config.headers["vendoo-transform-fields"],
      []
    );

    for (let field of transformFields) {
      const handler = transformHandlers[field.type];
      if (!handler) continue;
      const fieldValue = get(config.data, field.fieldPath);
      const newValue = handler({
        data: fieldValue,
        type: field.type,
        [field.type]: field[field.type],
      });
      set(config.data, field.fieldPath, newValue);
    }

    delete config.headers["vendoo-transform-fields"];

    return config;
  }
  return config;
};
