import { MarketplaceConnectDetailsType } from "@vendoo/marketplaces/src/urls";

/**
 * All the images are sent to Kidizen in the same request,
 * for this reason we need to be carefully with that request,
 * so we are scaling the images to the Kidizen specified size of 1242
 * in this way we can send more images in the same request.
 */
export const MAX_NUMBER_OF_IMAGES = 10;
export const IMAGE_SIZE = 1242;
export const MAX_TITLE_LENGTH = 255;

