export const KIDIZEN = {
  baseUrl: "https://www.kidizen.com",
  createListingUrl: function(itemURL: string) {
    if (/^items\/.*/.test(itemURL)) return `${this.baseUrl}/${itemURL}`;
    return `${this.baseUrl}/items/${itemURL}`;
  },
  createUrl: "https://www.kidizen.com/items/new",
  profileUrl: "https://www.kidizen.com/settings/profile",
  limitItems: 50,
  listingURLPattern: "https://www.kidizen.com/items/slug",
  imageLimit: MAX_NUMBER_OF_IMAGES,
};

