import {
  SyncInitiatorType,
  SyncType,
} from "@vendoo/common/types/importer/types/sync";

export const globalSyncVersion = 3;

const ONE_MIN = 60 * 1000;
const ONE_HOUR = 60 * ONE_MIN;
const ONE_DAY = 24 * ONE_HOUR;

export const SYNC_MINIMUM_INTERVAL = 1000 * 20; // 20 seconds

// Amount of time each type of sync will be disabled
export const AUTO_SYNC_DELAY_IN_MINUTES = 15; // 15 min
export const AUTO_SYNC_DELAY_IN_HOURS = 60 / AUTO_SYNC_DELAY_IN_MINUTES;
export const AUTO_SYNC_DELAY = AUTO_SYNC_DELAY_IN_MINUTES * ONE_MIN;

// Amount of time to avoid executing clear and sync again
export const CLEAR_SYNC_DELAY_IN_HOURS = 72; // 3 days
export const CLEAR_SYNC_DELAY = CLEAR_SYNC_DELAY_IN_HOURS * ONE_HOUR;

// Amount of time to wait until force "clear and sync"
export const CLEAR_SYNC_FORCE_TIME_IN_HOURS = 7 * 24; // 7 days
export const CLEAR_SYNC_FORCE_TIME = CLEAR_SYNC_FORCE_TIME_IN_HOURS * ONE_HOUR;

export const DEFAULT_SYNC_INVENTORY_LIMIT = 45_000;

export const AUTO_SYNC_DELAY_CONFIG = {
  API: {
    vendooLogin: 7 * ONE_DAY,
    marketplaceGranted: 1 * ONE_HOUR,
    enterImporterPage: 1 * ONE_HOUR,
  },
  EXTENSION: {
    vendooLogin: 15 * ONE_MIN,
    marketplaceGranted: 15 * ONE_MIN,
    enterImporterPage: 15 * ONE_MIN,
  },
} as const;

const shouldForceClearAndSync = (
  type: SyncInitiatorType,
  lastClearSyncDate?: number
) =>
  type === "auto" &&
  lastClearSyncDate &&
  Date.now() - lastClearSyncDate >= CLEAR_SYNC_FORCE_TIME;

const shouldForceCursorSync = (
  type: SyncInitiatorType,
  lastClearSyncDate?: number
) =>
  type === "user" &&
  lastClearSyncDate &&
  Date.now() - CLEAR_SYNC_DELAY < lastClearSyncDate;

export const getSyncType = (
  initiator: SyncInitiatorType,
  lastClearSyncDate?: number
): SyncType => {
  if (shouldForceClearAndSync(initiator, lastClearSyncDate)) return "clear";
  if (shouldForceCursorSync(initiator, lastClearSyncDate)) return "cursor";
  // Defaults
  if (initiator === "auto") {
    return "cursor";
  } else {
    return "clear"; // user
  }
};
