import { getSafeStorage } from "./getStorage";
import { Logger } from "@vendoo/common/context/shared/resolve";

// Types
import { StorageKeyType } from "./types";

export const getKeyValueStore = <T extends string = string>(
  key: string,
  storageType: StorageKeyType = "localStorage"
) => {
  const storage = getSafeStorage(storageType);

  const fireLocalChangeEvent = (newValue?: T) => {
    const oldValue = storage.getItem(key);

    const event = new StorageEvent("storage", {
      key,
      oldValue,
      newValue,
      storageArea: storage.__storage,
    });
    Object.defineProperty(event, "isLocal", {
      value: true,
    });
    window.dispatchEvent(event);
  };

  const clean = () => {
    fireLocalChangeEvent();
    storage.removeItem(key);
  };

  const get = () => (storage.getItem(key) ?? undefined) as T | undefined;

  const set = (value?: T) => {
    if (!value) {
      return clean();
    }
    fireLocalChangeEvent(value);
    storage.setItem(key, value);
  };

  const parse = <T>(defaultValue?: any): T => {
    try {
      const data = get();

      if (data) {
        return JSON.parse(data);
      }
    } catch (error) {
      Logger().warn("[getKeyValueStore]:" + (error as any)?.message);
    }
    return defaultValue;
  };

  return {
    parse,
    key,
    clean,
    get,
    set,
    onData: (cb: (val?: T) => any) => {
      const listener = (e: StorageEvent) => {
        if (e.key !== key) return; // react just to desired key
        cb(e.newValue === null ? undefined : (e.newValue as T));
      };
      window.addEventListener("storage", listener);
      return () => window.removeEventListener("storage", listener);
    },
  };
};
