import userEvent from "@testing-library/user-event";
import { getWaitForElementSelector } from "@vendoo/common/extension/utils/waitElement";
import {
  ClickActionType,
  ExecPageScriptActionsType,
} from "@vendoo/common/types/v2/messaging/ExecPageScript";

const isClickAction = (
  action: ExecPageScriptActionsType
): action is ClickActionType => action && action.type === "click";

export const clickActionHandler = async (
  action: ExecPageScriptActionsType,
  rootFrameElement: HTMLElement
) => {
  if (!isClickAction(action)) return;

  const element = await getWaitForElementSelector(action.isxPath)(
    action.selector,
    action.attempts,
    rootFrameElement
  );

  userEvent.click(element);
};
