import { handleException } from "@vendoo/common/errors/handle";
import { VendooError } from "@vendoo/common/errors/vendoo";
import { ElementNotFoundError } from "@vendoo/common/extension/utils/waitElement/error/ElementNotFoundError";
import {
  ExecPageScriptPayloadType,
  ExecPageScriptResultDetailsType,
  ExecPageScriptResultType,
} from "@vendoo/common/types/v2/messaging/ExecPageScript";

import { handleAction } from "./handleAction";

export const execPageScriptHandler = async (
  payload: ExecPageScriptPayloadType
): Promise<ExecPageScriptResultType> => {
  const actionsResultDetails: Array<ExecPageScriptResultDetailsType> = [];
  let success = true;

  for (let action of payload.actions) {
    const startTime = new Date().getTime();
    const resultDetails: ExecPageScriptResultDetailsType = {
      type: action.type,
      name: action?.name || "",
      timeMs: 0,
    };

    try {
      const result = await handleAction(action);
      resultDetails.result = result;
    } catch (e) {
      if (!action.isOptional) {
        resultDetails.error = handleException(
          e instanceof ElementNotFoundError ? new VendooError(e.message) : e
        );
        success = false;
      }

      if (action.breakOnFailure) {
        break;
      }
    }
    const endTime = new Date().getTime();
    resultDetails.timeMs = endTime - startTime;
    actionsResultDetails.push(resultDetails);
  }

  return {
    actionsResultDetails,
    success,
  };
};
