// Utils
import {
  AllMarketplaceIDType,
  DeprecatedMarketplaceType,
} from "@vendoo/common/types/v1/database/firebase.db.type";
import titleCase from "@vendoo/common/utils/titleCase";

/**
 * Use it to get the official name of marketplaces
 * @param marketplaceID
 * @returns string
 */
export const marketplaceNames = (
  marketplaceID:
    | AllMarketplaceIDType
    | "general"
    | DeprecatedMarketplaceType
    | "vendoo"
) => {
  switch (marketplaceID) {
    case "general":
    case "vendoo":
      return "Vendoo";
    case "ebay":
      return "eBay";
    case "the-realreal":
      return "TheRealReal";
    case "in-person":
      return "In-Person";
    case "sellhound":
      return "SellHound";
    case "craigslist":
      return "Craigslist";
    case "offerup":
      return "OfferUp";
    case "vestiaire-collective":
    case "vestiaire":
      return "Vestiaire Collective";
    case "vestiaireApi":
      return "Vestiaire Collective (EN)";
    case "whatnot":
      return "Whatnot";
    default:
      return titleCase(marketplaceID);
  }
};

/**
 * Use it to get shorten versions of marketplace names for places where space is limited
 * @param marketplaceID
 * @returns string
 */
export const shortMarketplaceNames = (
  marketplaceID: AllMarketplaceIDType | "general" | DeprecatedMarketplaceType
) => {
  switch (marketplaceID) {
    case "vestiaire-collective":
    case "vestiaire":
      return titleCase(marketplaceID);
    default:
      return marketplaceNames(marketplaceID);
  }
};
