import "../../common/setup/contentScript";

import { ExtensionV3ExecPageScriptCommand } from "@vendoo/common/messaging/connection/types";
import { ExecPageScriptResultType } from "@vendoo/common/types/v2/messaging/ExecPageScript";
import { execPageScriptHandler } from "../../serviceWorker/services/execPageScript/content";
import { Logger } from "@vendoo/common/context/shared/resolve";

const handleMessage = (
  message: ExtensionV3ExecPageScriptCommand,
  _sender: any,
  sendResponse: (response: ExecPageScriptResultType) => void
) => {
  const logger = Logger()
    .extend("ExecPageScript")
    .extend("MessageHandler")
    .trace({
      page: window?.location?.origin,
      messageId: message.id,
      messageName: message.name,
    });

  if (message.name !== "EXEC_PAGE_SCRIPT") {
    logger.debug("Ignoring message. Not EXEC_PAGE_SCRIPT.", {
      messageId: message.id,
      messageName: message.name,
    });
    return;
  }

  logger.debug("Valid ExecPageScript message received.", {
    messageId: message.id,
  });

  execPageScriptHandler(message.payload).then(result => {
    logger.debug("ExecPageScript finished.", result);
    return sendResponse(result);
  });

  // this tells Chrome that we'll use
  // sendResponse asynchronously
  // after this function finishes
  return true;
};

chrome.runtime.onMessage.addListener(handleMessage);
