export type FormatNumberOptions = {
  decimals?: number;
  decimalSeparator?: string;
  thousandSeparator?: string;
};

export type FormatCurrencyOptions = FormatNumberOptions & {
  currencySymbol?: string;
};

export function formatNumber(
  value?: number | bigint | null,
  opts: FormatNumberOptions = {}
) {
  const {
    decimals = 2,
    decimalSeparator = ".",
    thousandSeparator = ",",
  } = opts;

  const asNumber = Number(value ?? 0);

  if (Number.isNaN(asNumber)) {
    return "0";
  }
  const numAsString = String(Number(value ?? 0).toFixed(decimals));

  const [integer, fraction = ""] = numAsString.split(".");

  return [integer.replace(/\B(?=(\d{3})+(?!\d))/g, thousandSeparator), fraction]
    .filter(Boolean)
    .join(decimalSeparator);
}

export function formatCurrency(
  value?: number | bigint | null | "" | undefined,
  opts: FormatCurrencyOptions = {}
) {
  if (value === "" || value === undefined || value === null) return "";

  const formatted = formatNumber(value, opts);
  const matches = /^(-)?(\d.*)$/.exec(formatted)!;

  const [, sign = "", num] = matches;

  return [sign, opts.currencySymbol ?? "$", num].join("");
}
/** end new possible publisheable lib */

