export const recalculateMercariPrice = (price: number) =>
  price ? price / 100 : 0;

export const toNumber = <T extends number | undefined>(
  value: unknown,
  defaultValue?: T
): T extends number ? number : number | undefined => {
  const valueType = typeof value;
  const isEmptyString = Boolean(valueType === "string" && !value);
  const defaultValueNum = isNumber(defaultValue)
    ? Number(defaultValue)
    : undefined;

  if (isEmptyString) return defaultValueNum as never;

  return isNumber(value) ? Number(value) : (defaultValueNum as never);
};

export const recalculateCentsPrice = (price: number) =>
  price ? price / 100 : 0;

export const calculatePercent = (total: number, completed: number) => {
  if (total <= 0) return "0%";
  return Math.floor((completed / total) * 100) + "%";
};

const isDecimal = (num: number) => num % 1 !== 0;

/**
 * Because certain decimal fractions cannot be accurately represented in binary,
 * we must work with the decimal and integer parts separately here.
 * Number("18.99") * 100 = 1898.9999999999998  |  Number("18.9") * 100 = 1889.9999999999998
 */
export const parseDecimal = (value: string | undefined | number) => {
  const MAX_DECIMAL = 2;
  const num = toNumber(value, 0);

  if (!isDecimal(num)) return num;

  let [base, decimal = ""] = toNumber(value, 0)
    .toString()
    .split(".");

  decimal = decimal.padEnd(MAX_DECIMAL, "0").slice(0, MAX_DECIMAL);

  return Number(`${base}.${decimal}`);
};
