import { supportedVintedMarketplaces } from "@vendoo/common/countries/marketplaces/vinted";

// Types
import { CountryCodeType } from "@vendoo/common/countries/types";
import { MarketplaceConnectDetailsType } from "../../urls";

/**
 * Let's start using this to support multiple countries
 */
export const getVintedUrls = (countryCode: CountryCodeType) => {
  const { url } = supportedVintedMarketplaces[countryCode];

  return {
    baseUrl: url,
    apiUrl: `${url}/api/v2`,
    createUrl: `${url}/items/new`,
    uploadImgUrl: `${url}/api/v2/photos`,
    inventoryUrl(userId: string) {
      return `${url}/api/v2/wardrobe/${userId}/items`;
    },
    getListedUrl(listedID: string) {
      return `${url}/items/${listedID}`;
    },
    getDelistUrl(listedID: string) {
      return `${url}/api/v2/items/${listedID}/delete`;
    },
    getItemUrl(listedID: string) {
      return `${url}/api/v2/item_upload/items/${listedID}`;
    },
    oAuthURL: `${url}/member/signup/select_type`,
    registerURL: `${url}/member/signup/select_type`,
    getSizeGroupsUrl(catalogId: string) {
      return `${url}/api/v2/size_groups?catalog_ids=${catalogId}`;
    },
    getCatalogAttributesUrl(catalogId: string) {
      return `${url}/api/v2/item_upload/catalog_attributes?catalog_id=${catalogId}`;
    },
    getConditionsUrl(catalogId: string) {
      return `${url}/api/v2/item_upload/conditions?catalog_id=${catalogId}`;
    },
    sendTwoFactorAuthCodeUrl(userId: string) {
      return `${url}/api/v2/users/${userId}/user_2fa`;
    },
    verifyTwoFactorAuthCodeUrl(userId: string, twoFactorAuthId: string) {
      return `${url}/api/v2/users/${userId}/user_2fa/${twoFactorAuthId}`;
    },
    resendTwoFactorAuthCodeUrl(userId: string, twoFactorAuthId: string) {
      return `${url}/api/v2/users/${userId}/user_2fa/${twoFactorAuthId}/resend`;
    },
    itemUploadUrl: `${url}/api/v2/item_upload/items`,
    refreshSessionUrl: `${url}/web/api/auth/refresh`,
    shippingSettings: `${url}/settings/shipping`,
    getPackageSizesUrl(categoryId: string) {
      return `${url}/api/v2/catalogs/${categoryId}/package_sizes`;
    },
  };
};

export const VINTED = {
  imageLimit: 20,
  minImageLimit: 3,
  saleDetectionPageSize: 20,
};

/**
 * Avoid using urls from this object, instead use `getVintedUrls`
 */
export const VINTED_CONNECT: MarketplaceConnectDetailsType = {
  marketplaceID: "vinted",
  oAuthURL: "https://www.vinted.co.uk/member/signup/select_type",
  registerURL: "https://www.vinted.co.uk/member/signup/select_type",
  baseURL: "vinted.co.uk",
  extension: true,
};

export const MAX_TITLE_LENGTH = 100;
