import { Logger } from "@vendoo/common/context/shared/resolve";
import { ActiveFormIDType } from "@vendoo/common/types/v1/database/firebase.db.type";

const GKE_MARKETPLACES: ActiveFormIDType[] = ["vestiaireApi", "ebay"];

/**
 * Determines if GKE endpoint should be used based on marketplace and feature flag
 * @param marketplaceId - The marketplace identifier
 * @param isFeatureFlagEnabled - Whether INTEGRATIONS_GKE flag is enabled
 * @returns true if GKE endpoint should be used
 */
export const shouldUseGKEEndpoint = (
  marketplaceId: ActiveFormIDType,
  isFeatureFlagEnabled: boolean
): boolean => {
  return GKE_MARKETPLACES.includes(marketplaceId) && isFeatureFlagEnabled;
};

/**
 * Gets the appropriate endpoint based on environment configuration
 * @returns The endpoint URL to use
 */
export const getGKEEndpoint = (): string => {
  if (process.env.GATSBY_WORK_ENV === "local") {
    return "http://localhost:3000";
  } else if (process.env.VENDOO_GKE_ENDPOINT) {
    return process.env.VENDOO_GKE_ENDPOINT;
  } else {
    const serverEndpoint = process.env.VENDOO_SERVER_ENDPOINT || "";
    return `${serverEndpoint}/msvc`;
  }
};

/**
 * Validates that required environment variables are set
 * @returns true if all required variables are set
 */
export const validateEndpointConfig = (): boolean => {
  if (process.env.GATSBY_WORK_ENV === "local") {
    return true;
  }

  if (!process.env.VENDOO_GKE_ENDPOINT && !process.env.VENDOO_SERVER_ENDPOINT) {
    Logger().exception(
      new Error(
        "Neither VENDOO_GKE_ENDPOINT nor VENDOO_SERVER_ENDPOINT is configured"
      ),
      "ENDPOINT_CONFIG_ERROR"
    );
    return false;
  }

  return true;
};
