type WebFlags = typeof WEB_ONLY;
type MobileFlags = typeof MOBILE_ONLY;
type BackendFlags = typeof BACKEND_ONLY;
type GlobalFlags = typeof GLOBAL_ONLY;
type EnterpriseFlags = typeof ENTERPRISE_ONLY;

// Enforce type checking to avoid having
// the same key defined in different objects
// pointing to different flags
type AllFlags = WebFlags &
  MobileFlags &
  BackendFlags &
  GlobalFlags &
  EnterpriseFlags;

export const FEATURES_FLAGS: AllFlags = {
  ...WEB_ONLY,
  ...MOBILE_ONLY,
  ...GLOBAL_ONLY,
  ...BACKEND_ONLY,
  ...ENTERPRISE_ONLY,
} as const;

export type FeatureKeyType = keyof typeof FEATURES_FLAGS;
export type FeatureValuesType = typeof FEATURES_FLAGS[FeatureKeyType];

export const FEATURES_FLAGS_TO_PERSIST: Partial<typeof FEATURES_FLAGS> = {
  CROSSLISTED_IMPORTER_V1: "egm-749-beta",
};

export const getFeatureFlagName = (flagKey: string) =>
  Object.keys(FEATURES_FLAGS).find(key =>
    FEATURES_FLAGS[key].includes(flagKey)
  ) ?? "";
