import { Logger } from "@vendoo/common/context/shared/resolve";
import { LoggerType } from "@vendoo/common/logger2/constructor";
import { sanitizeStoreUrl } from "./sanitizeStoreUrl";

export const MAX_NUMBER_OF_IMAGES = 250;
export const MAX_TITLE_LENGTH = 255;
export const MAX_BRAND_LENGTH = 255;
export const MAX_SKU_LENGTH = 255;
export const MAX_BARCODE_LENGTH = 255;
export const MAX_TAG_LENGTH = 255;

const NEW_ADMIN_URL_REGEX = /^https?:\/\/admin.shopify.com\/store\/([^/?]+)\/?$/i;
const OLD_ADMIN_URL_REGEX = /^https?:\/\/([^.]+).myshopify.com\/admin\/?$/i;
export const SHOPIFY = {
  baseUrl: "https://www.shopify.com",
  createListingUrl: function(adminURL: string, itemID: string) {
    return `${SHOPIFY.getAdminConnectionURL(adminURL)}products/${itemID}`;
  },
  createListingUrlFromShopId: (shopId: string, itemId: string) => {
    const shop = shopId.split(".").at(0);
    return `https://admin.shopify.com/store/${shop}/products/${itemId}`;
  },
  dateFieldId: { id: "dateCreated", label: "Created At" },
  extractItemId: (id: string) => id.split("/").pop() || "",
  defaultListingStatus: "ACTIVE",
  listingURLPattern:
    "https://admin.shopify.com/store/storename/products/number or https://storename.myshopify.com/products/product-name",
  tagsLimit: 40,
  imageLimit: 16,

  getApiBaseURL: (adminURL: string) => {
    const logger = Logger().extend("fn:getApiBaseURL");
    logger.debug("getApiBaseURL", { adminURL });
    const shopId = SHOPIFY.extractShopId(adminURL, logger);
    return SHOPIFY.isNewAdminURL(adminURL)
      ? `https://admin.shopify.com/api/shopify/${shopId}`
      : `https://${shopId}.myshopify.com/admin`;
  },

  isValidUrlConnection: (adminURL: string) =>
    SHOPIFY.isOldAdminURL(adminURL) || SHOPIFY.isNewAdminURL(adminURL),

  isNewAdminURL: (adminURL: string) => NEW_ADMIN_URL_REGEX.test(adminURL),

  isOldAdminURL: (adminURL: string) => OLD_ADMIN_URL_REGEX.test(adminURL),

  extractShopId: (adminURL: string, logger: LoggerType = Logger()) => {
    const shopId =
      adminURL.match(OLD_ADMIN_URL_REGEX)?.[1] ??
      adminURL.match(NEW_ADMIN_URL_REGEX)?.[1] ??
      "";
    if (!shopId) {
      logger.warn("Error extract ShopId", {
        adminURL,
      });
    }
    return shopId;
  },

  getAdminConnectionURL: (adminURL: string) => {
    let urlToConnect = adminURL;

    if (SHOPIFY.isOldAdminURL(urlToConnect)) {
      const shopId = SHOPIFY.extractShopId(adminURL);
      urlToConnect = `https://admin.shopify.com/store/${shopId}/`;
    }
    return sanitizeStoreUrl(urlToConnect);
  },
  connectionPath: (userId: string) => `/users/${userId}/meta/shopify`,
};
