import { getWaitForElementSelector } from "@vendoo/common/extension/utils/waitElement";
import setInput from "@vendoo/common/extension/utils/form/set-input";
import {
  ExecPageScriptActionsType,
  UploadImagesType,
} from "@vendoo/common/types/v2/messaging/ExecPageScript";

const isUploadImageAction = (
  action: ExecPageScriptActionsType
): action is UploadImagesType => action && action.type === "uploadImages";

export const uploadImagesActionHandler = async (
  action: ExecPageScriptActionsType,
  rootFrameElement: HTMLElement
) => {
  if (!isUploadImageAction(action)) return;

  const selector = getWaitForElementSelector(action.payload.isxPath);

  const element = await selector<HTMLInputElement>(
    action.payload.selector,
    undefined,
    rootFrameElement
  );

  const files = action.payload.imagesBase64.map((imgDataURL, index) => {
    const u8bytes = atob(imgDataURL.split(",").pop() || "")
      .split("")
      .map(c => c.charCodeAt(0));
    const u8arr = new Uint8Array(u8bytes);
    const file = new File([u8arr], `img-${index}.jpeg`, {
      type: "image/jpeg",
    });

    return file;
  });

  const container = new DataTransfer();
  files.forEach(file => container.items.add(file));
  element.files = container.files;

  await setInput(element, container.files, {
    propName: "files",
  });
};
