import wait from "@vendoo/common/utils/wait";
import { TIME_TO_WAIT } from "@vendoo/common/utils/constants";
import { ElementNotFoundError } from "./error/ElementNotFoundError";

export const findHTMLElementFromPage = (
  xpath: string,
  container?: Node | HTMLElement
): Node | null | HTMLElement => {
  // Keep in mind in the xpath
  // 1. if the it is like "//a[text()='SearchingText']" it will search over all the document
  // 2. if the it is like ".//a[text()='SearchingText']" it will search over the container that you pass
  return document.evaluate(
    xpath,
    container || document,
    null,
    XPathResult.FIRST_ORDERED_NODE_TYPE,
    null
  ).singleNodeValue;
};
if (process.env.NODE_ENV === "development" && typeof window === "object") {
  window["findHTMLElementFromPage"] = findHTMLElementFromPage;
}

const printElement = (el: HTMLElement) => {
  try {
    return `${el.toString()}.${el.className ?? ""}#${el.id ?? ""}`;
  } catch (err) {
    return el.toString();
  }
};

const waitForElement = async <
  T extends HTMLElement | Node = HTMLElement | Node
>(params: {
  container?: HTMLElement | null;
  selector?: string;
  xPath?: string;
  attempts?: number;
}): Promise<T> => {
  const container = params.container ?? document;
  const maxAttempts = params.attempts ?? 10;

  const select = params.xPath
    ? findHTMLElementFromPage.bind(0, params.xPath, container)
    : params.selector
    ? container.querySelector.bind(container, params.selector)
    : null;

  if (!select) throw new Error("Empty selector");

  let curAttempt = 0;
  while (curAttempt < maxAttempts) {
    const el = select();
    if (el) return el as T;

    curAttempt++;
    await wait(TIME_TO_WAIT);
  }

  throw new ElementNotFoundError(
    `Element not found. Query ${params.xPath ??
      params.selector} Container ${printElement(container as HTMLElement)}`
  );
};

export const waitForElementSelector = async <T extends HTMLElement>(
  selector: string,
  attempts = 10,
  container?: HTMLElement
) =>
  waitForElement<T>({
    selector,
    attempts,
    container,
  });

export const waitForElementSelectorInContainer = async <T extends HTMLElement>(
  selector: string,
  container?: HTMLElement | null,
  attempts = 10
) =>
  waitForElement<T>({
    selector,
    attempts,
    container,
  });

export const waitForElementXPath = async <T extends HTMLElement>(
  xPath: string,
  attempts = 10,
  container?: HTMLElement
) =>
  waitForElement<T>({
    xPath,
    attempts,
    container,
  });

export const waitForElementXPathInContainer = async <
  T extends HTMLElement = HTMLElement
>(
  xPath: string,
  container?: HTMLElement | null,
  attempts = 10
) =>
  waitForElement<T>({
    xPath,
    attempts,
    container,
  });

export const getWaitForElementSelector = (isxPath?: boolean) =>
  isxPath ? waitForElementXPath : waitForElementSelector;
