// Types
import {
  StorageFallback,
  MemoryStorageFallback,
  MemoryStorage,
} from "./memory";
import { StorageKeyType } from "./types";

export const getSafeStorage = (
  storageType: StorageKeyType
): StorageFallback => {
  // If currently on tests environment
  if (typeof window === "undefined" || !window[storageType])
    return MemoryStorageFallback(MemoryStorage());

  if (!window["__memoryStorage"]) {
    window["__memoryStorage"] = MemoryStorage();
  }

  const fallbackStore = window["__memoryStorage"] as Storage;

  const selectedStorage = window[storageType] as Storage;

  return MemoryStorageFallback(selectedStorage, fallbackStore);
};
