import { css } from "styled-components";

import { colors, spacing } from "@vendoo/components/src/styles/variables";

// Types
import { RenderParamsType } from "../types";

const getTitleColor = (theme: RenderParamsType["theme"]) => {
  if (theme === "success") return colors.greenDark;
  if (theme === "error") return colors.red;

  return colors.black;
};

const getBorderColor = (theme: RenderParamsType["theme"]) => {
  if (theme === "success") return colors.greenDark;
  if (theme === "error") return colors.redDark;

  return colors.purple;
};

const getPosition = (position: RenderParamsType["position"]) => {
  if (position === "right-bottom")
    return css`
      position: fixed;
      bottom: ${spacing.medium}px;
      right: ${spacing.medium}px;
    `;

  if (position === "right-top")
    return css`
      position: fixed;
      top: ${spacing.medium}px;
      right: ${spacing.medium}px;
    `;

  return css`
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
  `;
};

export const commonStyle = css`
  text-transform: initial;
  font-family: sans-serif;
  line-height: initial;
  letter-spacing: initial;
  box-sizing: border-box;
`;

export const customStyles = {
  getTitleColor,
  getBorderColor,
  getPosition,
};
