import userEvent from "@testing-library/user-event";
import { getWaitForElementSelector } from "@vendoo/common/extension/utils/waitElement";
import setInput from "@vendoo/common/extension/utils/form/set-input";
import {
  ExecPageScriptActionsType,
  SetInputType,
} from "@vendoo/common/types/v2/messaging/ExecPageScript";

const isSetInputAction = (
  action: ExecPageScriptActionsType
): action is SetInputType => action && action.type === "setInput";

export const setInputActionHandler = async (
  action: ExecPageScriptActionsType,
  rootFrameElement: HTMLElement
) => {
  if (!isSetInputAction(action)) return;

  const selector = getWaitForElementSelector(action.payload.isxPath);

  const element = await selector<HTMLInputElement>(
    action.payload.selector,
    action.payload.attempts,
    rootFrameElement
  );

  if (action.payload.delayMs) {
    if (["INPUT", "TEXTAREA"].includes(element.tagName))
      userEvent.clear(element);
    await userEvent.type(element, String(action.payload.value), {
      delay: action.payload.delayMs,
    });
    return;
  }

  await setInput(element, action.payload.value);
};
