import set from "lodash/set";
import get from "lodash/get";

import { getKeyValueStore } from "@vendoo/common/utils/storage";

// Types
import { GetFromStorage } from "@vendoo/common/types/v2/messaging/ExecPageScript";

/**
 * This function is in a separate file because it is using lodash and
 * we must not use lodash directly in the actions because it will cause
 * errors with the etsy copyPaste
 */
export const getFromStorage = (action: GetFromStorage) => {
  const storageValue = getKeyValueStore(action.key, action.storageSource);

  let result = "";

  if (action.properties) {
    const data = storageValue.parse<object>({});
    result = JSON.stringify(
      action.properties.reduce((acc, property) => {
        const value = get(data, property);
        set(acc, property, value);
        return acc;
      }, {})
    );
  } else {
    result = storageValue.get() || "";
  }

  return result;
};
