// Types
import { ExecPageScriptActionsType } from "@vendoo/common/types/v2/messaging/ExecPageScript";
import { actionHandlers } from "./actionHandlers";
import { shouldBypassAction } from "@vendoo/extension-v3/src/serviceWorker/services/execPageScript/content/handleAction/utils/shouldBypassAction";

function getFrameDocument(
  selectors: string[],
  element: HTMLElement = document.body
): HTMLElement {
  const [firstSelector, ...restSelectors] = selectors;
  if (!firstSelector) return element;

  const nextFrameElement =
    element.querySelector(firstSelector)?.["contentDocument"] ?? element;

  return getFrameDocument(restSelectors, nextFrameElement);
}

/**
 * # IMPORTANT
 * - Don t use lodash here, because it will cause an error with etsy copy paste
 */
export const handleAction = async (action: ExecPageScriptActionsType) => {
  const rootFrameElement: HTMLElement =
    "rootFrameSelectors" in action && Array.isArray(action.rootFrameSelectors)
      ? getFrameDocument(action.rootFrameSelectors)
      : document.body;

  const handler = actionHandlers[action.type];

  if (action.preValidation) {
    const shouldExecAction = await shouldBypassAction(
      action.preValidation,
      rootFrameElement
    );

    if (shouldExecAction) return;
  }
  return handler(action, rootFrameElement);
};

if (process.env.NODE_ENV === "development") {
  window["__handleAction"] = handleAction;
}
