import { getStyles } from "./styles";
import { VendooLogo } from "./logo";

// Types
import { VendooModalParamsType, RenderParamsType } from "./types";

export const VENDOO_MODAL = {
  id: "vendoo-container-modal",
};

export const vendooModal = {
  remove: (container?: HTMLElement) => {
    const element = container || document;
    const modal = element.querySelector(`#${VENDOO_MODAL.id}`);
    modal?.remove();
  },
  create: (params: VendooModalParamsType) => {
    const init = ({ theme, hasBackdrop, position }: RenderParamsType) => {
      const styles = getStyles({ theme, position });

      const backdrop = document.createElement("div");
      const container = document.createElement("div");
      const title = document.createElement("h1");
      const logo = document.createElement("span");
      const close = document.createElement("button");
      const wrapper = document.createElement("div");

      logo.innerHTML = VendooLogo;
      title.innerHTML = params.title;
      close.innerHTML = "X";

      backdrop.setAttribute("style", styles.backdrop.join(""));
      title.setAttribute("style", styles.title.join(""));
      logo.setAttribute("style", styles.logo.join(""));
      container.setAttribute("style", styles.container.join(""));
      close.setAttribute("style", styles.close.join(""));
      wrapper.setAttribute("style", styles.wrapper.join(""));

      close.addEventListener("click", () => vendooModal.remove(), {
        once: true,
      });

      container.appendChild(logo);
      container.appendChild(title);
      container.appendChild(close);
      wrapper.appendChild(container);

      if (params.description) {
        const description = document.createElement("p");

        description.setAttribute("style", styles.description.join(""));
        description.innerHTML = params.description;
        container.appendChild(description);
      }

      if (hasBackdrop) {
        backdrop.id = VENDOO_MODAL.id;
        backdrop.appendChild(wrapper);
        return backdrop;
      }

      wrapper.id = VENDOO_MODAL.id;

      return wrapper;
    };

    const render = (params: RenderParamsType) => {
      const modal = init(params);

      if (params.container) {
        vendooModal.remove(params.container);
        params.container.appendChild(modal);
      } else {
        const body = document.querySelector("body") as HTMLElement;
        vendooModal.remove();
        body.appendChild(modal);
      }
    };

    return { render };
  },
};
