import { MercariErrorResType } from "@vendoo/common/types/mercari/Errors";

/**
 * @TODO Map error messages to something better for Vendoo users to understand
 */
export default (
  errors: MercariErrorResType["errors"],
  defaultError: string
): string => {
  if (Array.isArray(errors) && errors.some(e => e.message)) {
    const length = errors.length - 1;
    let message = errors.length
      ? errors.reduce(
          (acc, error, index) =>
            // Mercari std error messages are punctuated already
            (acc += `${error.message}${index !== length ? " " : ""}`),
          ""
        )
      : defaultError;

    return message;
  }

  return defaultError;
};
