import { vendooModal } from "@vendoo/extension-v3/src/common/vendooModal";
import {
  ExecPageScriptActionsType,
  RenderModalType,
} from "@vendoo/common/types/v2/messaging/ExecPageScript";

const isRenderModalAction = (
  action: ExecPageScriptActionsType
): action is RenderModalType => action && action.type === "renderModal";

export const renderModalHandler = async (
  action: ExecPageScriptActionsType,
  _rootFrameElement: HTMLElement
) => {
  if (!isRenderModalAction(action)) return;

  const { theme, position, hasBackdrop, ...params } = action.payload;
  const modal = vendooModal.create(params);

  modal.render({ theme, position, hasBackdrop });
};
