import wait from "@vendoo/common/utils/wait";
import fireEvent from "./fireEvent";

type SetInputOptions = {
  delayAfterChange?: number;
  propName?: "value" | "files" | "checked";
  container?: HTMLElement;
};

export const setInputValue = (
  element: HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement,
  value: any
) => {
  const valueObj =
    Object.getOwnPropertyDescriptor(Object.getPrototypeOf(element), "value") ||
    {};

  if (valueObj.set) valueObj.set.call(element, value);
  else element.value = value;
};

const setInput = async <T extends HTMLInputElement | HTMLTextAreaElement>(
  input: T | null,
  fieldValue: any,
  opt: SetInputOptions = {}
) => {
  const { delayAfterChange = 100, propName = "value" } = opt;

  if (!input || typeof fieldValue === "undefined")
    throw new Error(
      `Failed to set to input. value: ${fieldValue} - field: ${input?.name}`
    );

  const success = fireEvent.change(input, {
    target: { [propName]: fieldValue },
  });

  if (!success) {
    throw new Error("failed to set input");
  }

  if (delayAfterChange) await wait(delayAfterChange);
};

export default setInput;
