import {
  ExecPageScriptActionsType,
  WaitActionType,
} from "@vendoo/common/types/v2/messaging/ExecPageScript";
import wait from "@vendoo/common/utils/wait";

const isWaitAction = (
  action: ExecPageScriptActionsType
): action is WaitActionType => action && action.type === "wait";

export const waitHandler = async (
  action: ExecPageScriptActionsType,
  _rootFrameElement: HTMLElement
) => {
  if (!isWaitAction(action)) return;
  return wait(action.timeMs);
};
