// eslint-disable-next-line
import { fireEvent as dtlFireEvent } from "@testing-library/dom/dist/events";
import { FireFunction, FireObject } from "@testing-library/react";

// react-testing-library's version of fireEvent will call
// dom-testing-library's version of fireEvent. The reason
// we make this distinction however is because we have
// a few extra events that work a bit differently
const fireEvent = ((el, ev) => dtlFireEvent(el, ev)) as FireFunction &
  FireObject;

Object.keys(dtlFireEvent).forEach(key => {
  fireEvent[key] = (...args: any[]) => dtlFireEvent[key](...args);
});

// React event system tracks native mouseOver/mouseOut events for
// running onMouseEnter/onMouseLeave handlers
// @link https://github.com/facebook/react/blob/b87aabdfe1b7461e7331abb3601d9e6bb27544bc/packages/react-dom/src/events/EnterLeaveEventPlugin.js#L24-L31
const mouseEnter = fireEvent.mouseEnter;
const mouseLeave = fireEvent.mouseLeave;
fireEvent.mouseEnter = (el, opt) => {
  mouseEnter(el, opt);
  return fireEvent.mouseOver(el, opt);
};
fireEvent.mouseLeave = (el, opt) => {
  mouseLeave(el, opt);
  return fireEvent.mouseOut(el, opt);
};

const pointerEnter = fireEvent.pointerEnter;
const pointerLeave = fireEvent.pointerLeave;
fireEvent.pointerEnter = (el, opt) => {
  pointerEnter(el, opt);
  return fireEvent.pointerOver(el, opt);
};
fireEvent.pointerLeave = (el, opt) => {
  pointerLeave(el, opt);
  return fireEvent.pointerOut(el, opt);
};

const select = fireEvent.select;
fireEvent.select = ((node, init) => {
  select(node, init);
  // React tracks this event only on focused inputs
  "focus" in node && node.focus();

  // React creates this event when one of the following native events happens
  // - contextMenu
  // - mouseUp
  // - dragEnd
  // - keyUp
  // - keyDown
  // so we can use any here
  // @link https://github.com/facebook/react/blob/b87aabdfe1b7461e7331abb3601d9e6bb27544bc/packages/react-dom/src/events/SelectEventPlugin.js#L203-L224
  fireEvent.keyUp(node, init);
}) as typeof select;

// React event system tracks native focusout/focusin events for
// running blur/focus handlers
// @link https://github.com/facebook/react/pull/19186
const blur = fireEvent.blur;
const focus = fireEvent.focus;
fireEvent.blur = (el, opt) => {
  fireEvent.focusOut(el, opt);
  return blur(el, opt);
};
fireEvent.focus = (el, opt) => {
  fireEvent.focusIn(el, opt);
  return focus(el, opt);
};

export default fireEvent;
