export const MAX_NUMBER_OF_IMAGES: {
  [k in MarketplaceIDType | "general"]: number;
} = (() => {
  const MAX_NUMBER_OF_IMAGES_MAP = {
    general: 0, // it has to be the maximum because only in the general form we upload the images
    ebay: EBAY.MAX_NUMBER_OF_IMAGES,
    etsy: ETSY.ETSY.imageLimit,
    poshmark: POSHMARK.POSHMARK.imageLimit,
    mercari: MERCARI.MERCARI.imageLimit,
    grailed: GRAILED.GRAILED.imageLimit,
    depop: DEPOP.DEPOP.imageLimit,
    tradesy: TRADESY.TRADESY.imageLimit,
    kidizen: KIDIZEN.KIDIZEN.imageLimit,
    facebook: FACEBOOK.FACEBOOK.imageLimit,
    shopify: SHOPIFY.SHOPIFY.imageLimit,
    vestiaire: VESTIAIRE.MAX_NUMBER_OF_IMAGES,
    vinted: VINTED.VINTED.imageLimit,
    whatnot: WHATNOT.WHATNOT.imageLimit,
    sellhound: 0,
    sellwild: SELLWILD.SELLWILD.imageLimit,
    vestiaireApi: VESTIAIRE_API.limits.image.max,
  };
  MAX_NUMBER_OF_IMAGES_MAP.general = Math.max(
    ...Object.values(MAX_NUMBER_OF_IMAGES_MAP)
  );
  return MAX_NUMBER_OF_IMAGES_MAP;
})();

