export const isExtensionMarketplace = (
  key: string
): key is ExtensionMarketplacesID => {
  return EXTENSION_MARKETPLACES.includes(key as ExtensionMarketplacesID);
};

export const isAPIMarketplace = (
  marketplaceID: MarketplaceIDType
): marketplaceID is ApiMarketplacesID => {
  return API_MARKETPLACES.includes(marketplaceID as ApiMarketplacesID);
};

export const isVendooSupportedMarketplace = (
  marketplaceID: string
): marketplaceID is MarketplaceIDType => {
  return MARKETPLACES.includes(marketplaceID as MarketplaceIDType);
};

