// Used to output the marketplace ID for each item label
export const MARKETPLACE_STATUS_LABEL_MAPPER = MARKETPLACES.map(
  marketplace => ({
    marketplace,
    marketplaceName: marketplaceNames(marketplace),
  })
).reduce((prev, { marketplace, marketplaceName }) => {
  prev[`${marketplaceName} Listed`] = marketplace;
  prev[`${marketplaceName} Not Listed`] = marketplace;
  return prev;
}, {} as MarketplaceStatusesPerLabel);

