export interface StorageFallback extends Storage {
  __storage: Storage;
}

export const MemoryStorageFallback = (
  storage: Storage,
  memory: Storage = MemoryStorage()
): StorageFallback => {
  return {
    __storage: storage,
    clear() {
      storage.clear();
      memory.clear();
    },
    getItem(k) {
      return storage.getItem(k) ?? memory.getItem(k);
    },
    key(i) {
      return storage.key(i) ?? memory.key(i);
    },
    get length() {
      return storage.get() ?? memory.length;
    },
    removeItem(k) {
      storage.removeItem(k);
      memory.removeItem(k);
    },
    setItem(k, v) {
      try {
        storage.setItem(k, v);
      } catch (err) {
        // Fallback to memory if storage is unavailable
      } finally {
        memory.setItem(k, v);
      }
    },
  };
};

export const MemoryStorage = (): Storage => {
  let cache: { [k: string]: string } = {};
  return {
    clear() {
      cache = {};
    },
    getItem(k) {
      return cache[k] ?? null;
    },
    key(i) {
      return Object.keys(cache)[i] ?? null;
    },
    get length() {
      return Object.keys(cache).length;
    },
    removeItem(k) {
      delete cache[k];
    },
    setItem(k, v) {
      cache[k] = v;
    },
  };
};
