import { AxiosRequestConfig } from "axios";

import { mercariConfigType } from "@vendoo/common/types/mercari/config";
import { FeatureFlagsEnableType } from "@vendoo/common/types/marketplaces";
import createImageFromBlob from "@vendoo/common/utils/createImageFromBlob";
import mercariBaseHeaders from "@vendoo/marketplaces/src/mercari/handlers/list/utils/baseHeaders";
import { MercariExtraType } from "@vendoo/common/types/v2/connections/extras/mercari";
import { VendooMercariItemType } from "@vendoo/common/types/mercari/VendooMercariItemType";

import { MERCARI } from "../../../utils/constants";

export const getListItemRequestConfig = ({
  config,
  extras,
  item,
}: {
  config: mercariConfigType;
  extras: MercariExtraType;
  item: VendooMercariItemType;
}) =>
  ({
    url: MERCARI.apiUrl,
    method: "POST",
    headers: mercariBaseHeaders(extras),
    data: {
      ...config.createListing,
      operationName: MERCARI.operations.createListing,
      variables: { input: item },
    },
  } as AxiosRequestConfig);

export const getMultiUploadImageRequestConfig = ({
  config,
  extras,
  images,
}: {
  config: mercariConfigType;
  extras: MercariExtraType;
  images: string[];
}) => {
  const vendooTransformFields: { fieldPath: string; type: "blob" }[] = [];
  const vendooTransformRequestFieldsOrder: string[] = [];
  const multiImageMap: Record<string, string[]> = {};
  const multiImageData: Record<string, string> = {};

  images.forEach((img, index) => {
    const fieldPath = `${index + 1}`;
    vendooTransformFields.push({ fieldPath, type: "blob" });
    vendooTransformRequestFieldsOrder.push(fieldPath);
    multiImageMap[fieldPath] = [`variables.input.photos.${index}`];
    multiImageData[fieldPath] = img;
  });

  return {
    url: MERCARI.uploadImgUrl,
    method: "POST",
    headers: {
      ...mercariBaseHeaders(extras),
      "Content-Type": "multipart/form-data",
      "vendoo-transform-fields": JSON.stringify(vendooTransformFields),
      "vendoo-transform-request": {
        type: "form-data",
        order: JSON.stringify([
          "operations",
          "map",
          ...vendooTransformRequestFieldsOrder,
        ]),
      },
      Origin: MERCARI.baseUrl,
      Referer: MERCARI.createUrl,
    },
    data: {
      operations: JSON.stringify({
        operationName: MERCARI.operations.uploadTempListingPhotos,
        variables: { input: { photos: [null] } },
        ...config.uploadTempListingPhotos,
      }),
      map: JSON.stringify(multiImageMap),
      ...multiImageData,
    },
  } as AxiosRequestConfig;
};

export const getUploadImageAsStringConfig = ({
  config,
  extras,
  imageData,
}: {
  config: mercariConfigType;
  extras: MercariExtraType;
  imageData: string;
}) =>
  ({
    url: MERCARI.uploadImgUrl,
    method: "POST",
    headers: {
      ...mercariBaseHeaders(extras),
      "Content-Type": "multipart/form-data",
      "vendoo-transform-fields": JSON.stringify([
        { fieldPath: "1", type: "blob" },
      ]),
      "vendoo-transform-request": {
        type: "form-data",
        order: JSON.stringify(["operations", "map", "1"]),
      },
      Origin: MERCARI.baseUrl,
      Referer: MERCARI.createUrl,
    },
    data: {
      operations: JSON.stringify({
        operationName: MERCARI.operations.uploadTempListingPhotos,
        variables: { input: { photos: [null] } },
        ...config.uploadTempListingPhotos,
      }),
      map: JSON.stringify({ "1": ["variables.input.photos.0"] }),
      "1": imageData,
    },
  } as AxiosRequestConfig);

export const getUploadRequestConfig = async (
  image: Blob,
  extras: MercariExtraType,
  config: mercariConfigType,
  _flags?: FeatureFlagsEnableType
): Promise<AxiosRequestConfig> => {
  const imageData = await createImageFromBlob(await image.arrayBuffer());
  return getUploadImageAsStringConfig({
    extras,
    config,
    imageData,
  });
};
