import { getWaitForElementSelector } from "@vendoo/common/extension/utils/waitElement";
import { PreValidationParams } from "@vendoo/common/types/v2/messaging/ExecPageScript";

export const shouldBypassAction = async (
  params: PreValidationParams,
  rootFrameElement: HTMLElement
) => {
  const {
    selector: elementSelector,
    isxPath,
    attibuteKey,
    attributeValue,
  } = params;

  const selector = getWaitForElementSelector(isxPath);

  const element = await selector(elementSelector, 2, rootFrameElement);

  //Action will not be skipped if element is not found
  if (!element) return false;

  const shouldSkipAction = attributeValue
    ? element.getAttribute(attibuteKey) === attributeValue
    : element.hasAttribute(attibuteKey);

  return shouldSkipAction;
};
