import {
  ExecPageScriptActionsType,
  SendRequestActionType,
} from "@vendoo/common/types/v2/messaging/ExecPageScript";
import { ExtensionV3WebRequestCommand } from "@vendoo/common/messaging/connection/types";

import { webRequest } from "../../../../webRequest";

const isSendRequestAction = (
  action: ExecPageScriptActionsType
): action is SendRequestActionType => action && action.type === "sendRequest";

export const sendRequestActionHandler = async (
  action: ExecPageScriptActionsType,
  _rootFrameElement: HTMLElement
) => {
  if (!isSendRequestAction(action)) return;

  try {
    const response = await webRequest(
      action.payload,
      {} as ExtensionV3WebRequestCommand
    );
    return JSON.stringify({ response });
  } catch (error) {
    return JSON.stringify({ error });
  }
};
