import { getWaitForElementSelector } from "@vendoo/common/extension/utils/waitElement";
import {
  ExecPageScriptActionsType,
  FireEventType,
} from "@vendoo/common/types/v2/messaging/ExecPageScript";

import fireEvent from "@vendoo/common/extension/utils/form/fireEvent";

const isFireEventAction = (
  action: ExecPageScriptActionsType
): action is FireEventType => action && action.type === "fireEvent";

export const fireEventHandler = async (
  action: ExecPageScriptActionsType,
  rootFrameElement: HTMLElement
) => {
  if (!isFireEventAction(action)) return;

  const selector = getWaitForElementSelector(action.isxPath);
  const element = await selector<HTMLInputElement>(
    action.selector,
    undefined,
    rootFrameElement
  );

  fireEvent[action.payload.eventType](element, action.payload.options);
  return;
};
