import { MercariExtraType } from "@vendoo/common/types/v2/connections/extras/mercari";

export default function mercariBaseHeaders(extras: MercariExtraType) {
  /**
   * Later we should make this something we can pull from firebase
   * (except for the tokens)
   */
  return {
    accept: "*/*",
    "content-type": "application/json",
    "x-app-version": "1",
    "x-double-web": "1",
    "x-gql-migration": "1",
    "x-platform": "web",
    "apollo-require-preflight": "true",
    "x-csrf-token": extras?.csrf,
    ...(extras?.accessToken
      ? { Authorization: `Bearer ${extras.accessToken}` }
      : {}),
  };
}

export const mercariBaseRestHeaders = (extras: MercariExtraType) => {
  return {
    accept: "application/json",
    "x-app-version": "318689",
    "x-app-release": "7.95.1",
    "x-platform": "android",
    "content-type": "application/protobuf",
    ...(extras?.accessToken
      ? { Authorization: `Bearer ${extras.accessToken}` }
      : {}),
  };
};
